type OrderEvent =
  | { type: 'order.placed.v1'; orderId: string; occurredAt: string }
  | { type: 'address.changed.v1'; customerId: string };
function assertNever(e: never): never { throw new Error(`unhandled event ${JSON.stringify(e)}`); }

function handle(e: OrderEvent): void {
  switch (e.type) {
    case 'order.placed.v1': return index.upsert(e.orderId);   // narrowed here
    case 'address.changed.v1': return cache.invalidate(e.customerId);
    default: return assertNever(e);
  }
}
